use std::{rc::Rc as LocalRc,cell::RefCell as LocalCell,io::Write};
#[derive(Clone)]struct Bytes(LocalRc<LocalCell<Vec<u8>>>);impl Write for Bytes{fn write(&mut self,b:&[u8])->std::io::Result<usize>{self.0.borrow_mut().extend_from_slice(b);Ok(b.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}
fn base64(bytes:&[u8])->String{let alphabet=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut out=String::new();for part in bytes.chunks(3){let v=((part[0]as u32)<<16)|((part.get(1).copied().unwrap_or(0)as u32)<<8)|part.get(2).copied().unwrap_or(0)as u32;for i in 0..4{out.push(if i>part.len(){'='}else{alphabet[((v>>(18-i*6))&63)as usize]as char});}}out}
fn output(mut f:impl FnMut(&mut dyn XmlWriter))->Value{let mut m=MemoryXmlWriter::new();f(&mut m);let units=m.getCodeUnits().iter().map(|v|format!("{v:04x}")).collect::<String>();let bytes=Bytes(LocalRc::new(LocalCell::new(vec![])));let mut b=BufferXmlWriter::new(Box::new(bytes.clone()));f(&mut b);b.flush();json!({"memoryResult":"ok","units":units,"bufferResult":"ok","bytes":base64(&bytes.0.borrow())})}
fn font(p:&Value)->Rc<FontFormatting>{let f=Rc::new(FontFormatting::new());f.setItalic(p["italic"].as_bool().unwrap());f.setStrikeout(p["strike"].as_bool().unwrap());f.setFontHeight(p["height"].as_i64().unwrap()as i32);f.setFontWeight(p["weight"].as_i64().unwrap()as i16);f.setEscapementType(p["escape"].as_i64().unwrap()as i16);f.setUnderlineType(p["underline"].as_i64().unwrap()as i16);f.setUnderlineTypeModified(p["underlineModified"].as_bool().unwrap());f.setFontColorIndex(p["color"].as_i64().unwrap()as i32);let flags=p["flags"].as_i64().unwrap();if flags&1!=0{f.setBoldOption();}if flags&2!=0{f.setItalicOption();}if flags&4!=0{f.setUnderlineOption();}if flags&8!=0{f.setColorOption();}if flags&16!=0{f.setStrikeOption();}f}
fn number(p:&Value)->Rc<NumberFormatFormatting>{Rc::new(NumberFormatFormatting::new(p["id"].as_i64().unwrap()as i32,p["code"].as_str().map(str::to_string)))}
fn history(input:&Value,book:&Rc<KmoBook>)->Value{let mut label=DifferentialFormattingLabel::DifferentialFormattingLabel(book.clone());let font=font(&input["fonts"][511]);let pattern=Rc::new(RefCell::new(PatternFormatting::PatternFormatting()));pattern.borrow_mut().setFillPattern(1);pattern.borrow_mut().setFillForegroundColor(-16711936);let border=Rc::new(RefCell::new(BorderFormatting::BorderFormatting()));border.borrow_mut().setBorderLeft(1);let num=number(&input["numbers"][5]);let df=Rc::new(RefCell::new(DifferentialFormatting::DifferentialFormatting__3(Some(font.clone()),Some(border.clone()),Some(pattern.clone()))));df.borrow_mut().setNumberFormatFormatting(Some(num.clone()));let data=DataFormatting::new();data.setFontFormatting(Some(font.clone()));data.setBorderFormatting(Some(border.clone()));data.setPatternFormatting(Some(pattern.clone()));data.setNumberFormatFormatting(Some(num.clone()));let mut out=vec![output(|w|label.write(w))];for i in 0..10{let id=match i{0=>label.addForWrite(None),1=>label.addForWrite__df(None),2=>label.addForWrite__pattern(None),3=>label.addForWrite__4(None,None,None,None),4|5=>label.addForWrite__df(Some(df.clone())),6=>label.addForWrite(Some(&data)),7=>label.addForWrite__pattern(Some(pattern.clone())),8=>label.addForWrite__4(Some(pattern.clone()),Some(border.clone()),Some(font.clone()),Some(num.clone())),_=>label.addForWrite__df(Some(Rc::new(RefCell::new(DifferentialFormatting::DifferentialFormatting()))))};if i==5{font.setItalic(false);font.setFontHeight(19);pattern.borrow_mut().setFillForegroundColor(-65536);df.borrow_mut().setNumberFormatFormatting(None);}let model=df.borrow();let identity=Rc::ptr_eq(model.fontFormatting.as_ref().unwrap(),&font)&&Rc::ptr_eq(model.borderFormatting.as_ref().unwrap(),&border)&&Rc::ptr_eq(model.patternFormatting.as_ref().unwrap(),&pattern);let numberSame=if i<5{Rc::ptr_eq(model.numberFormatFormatting().as_ref().unwrap(),&num)}else{model.numberFormatFormatting().is_none()};out.push(json!({"id":id,"output":output(|w|label.write(w)),"modelIdentity":identity,"numberSame":numberSame}));}json!(out)}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
