fn original_android_differential_model_font_number_and_write_history(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/dxf-r0b39");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();KmoLocale::setLocale(java["locale"].as_str().unwrap().into());kfc::cn::wps::kfc::numfmt::i18n::KmoLang::KmoLang::setLocale(java["locale"].as_str().unwrap().into());KmoXFManager::loadBuiltinFormats();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();book.getXFManager().borrow().addFormat(164,"0.0000<&>\n".into());let label=DifferentialFormattingLabel::DifferentialFormattingLabel(book.clone());let fonts:Vec<_>=input["fonts"].as_array().unwrap().iter().map(|p|output(|w|label.writeFont(w,&font(p)))).collect();let numbers:Vec<_>=input["numbers"].as_array().unwrap().iter().map(|p|output(|w|label.writeNumFmt(w,&number(p)))).collect();let native=json!({"locale":KmoLocale::getDefault(),"fonts":fonts,"numbers":numbers,"history":history(&input,&book)});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&native).unwrap()).unwrap();compare(&native,&java,"root");}
